"""
Task 012 — Parse a date string

Interprets the spec as: support common date formats a user might type,
returning (year, month, day) as integers, raising ValueError on failure.

Supported formats include (but are not limited to):
  - ISO-style: YYYY-MM-DD, YYYY/MM/DD, YYYY.MM.DD
  - US-style:  MM/DD/YYYY, MM-DD-YYYY, MM.DD.YYYY
  - Long month: "March 15, 2024", "15 March 2024", "March 15 2024"
  - Short month: "Mar 15, 2024", "15 Mar 2024"
  - Two-digit years are interpreted as 2000+ if <= 68, else 1900+
    (same heuristic as strptime).
"""

import re
from datetime import datetime

# ---------------------------------------------------------------------------
# Month name tables
# ---------------------------------------------------------------------------
_MONTH_FULL = {
    "january": 1, "february": 2, "march": 3, "april": 4,
    "may": 5, "june": 6, "july": 7, "august": 8,
    "september": 9, "october": 10, "november": 11, "december": 12,
}
_MONTH_ABBR = {
    "jan": 1, "feb": 2, "mar": 3, "apr": 4,
    "may": 5, "jun": 6, "jul": 7, "aug": 8,
    "sep": 9, "oct": 10, "nov": 11, "dec": 12,
}


def _month_from_name(name: str) -> int:
    """Convert month name (full or abbreviated) to integer 1-12."""
    key = name.lower()
    if key in _MONTH_FULL:
        return _MONTH_FULL[key]
    if key in _MONTH_ABBR:
        return _MONTH_ABBR[key]
    raise ValueError(f"Unknown month name: {name!r}")


def _fix_year(y: int) -> int:
    """Expand two-digit year using the same rule as Python's strptime."""
    if y < 100:
        return y + 2000 if y <= 68 else y + 1900
    return y


def _validate(year: int, month: int, day: int) -> tuple[int, int, int]:
    """Validate that the combination is a real calendar date."""
    # Use datetime to validate; it raises ValueError on bad dates.
    datetime(year, month, day)
    return (year, month, day)


# ---------------------------------------------------------------------------
# Format patterns (tried in order)
# ---------------------------------------------------------------------------
# Each pattern is (regex, extractor_function)
# The extractor receives the re.Match and returns (year, month, day) ints
# or raises ValueError.

_SEP = r"[-/.\s]"          # common separators

_PATTERNS = []


def _register(pattern):
    """Decorator to register a (compiled_regex, handler) pair."""
    def decorator(fn):
        _PATTERNS.append((re.compile(pattern, re.IGNORECASE), fn))
        return fn
    return decorator


# --- YYYY-MM-DD / YYYY/MM/DD / YYYY.MM.DD ---
@_register(r"^\s*(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})\s*$")
def _iso(m):
    return _validate(_fix_year(int(m.group(1))), int(m.group(2)), int(m.group(3)))


# --- MM/DD/YYYY or MM-DD-YYYY or MM.DD.YYYY (separator must be consistent) ---
@_register(r"^\s*(\d{1,2})([-/.])(\d{1,2})\2(\d{4})\s*$")
def _us_long_year(m):
    return _validate(_fix_year(int(m.group(4))), int(m.group(1)), int(m.group(3)))


# --- MM/DD/YY (two-digit year, consistent separator) ---
@_register(r"^\s*(\d{1,2})([-/.])(\d{1,2})\2(\d{2})\s*$")
def _us_short_year(m):
    return _validate(_fix_year(int(m.group(4))), int(m.group(1)), int(m.group(3)))


# --- "Month DD, YYYY" or "Month DD YYYY" ---
@_register(r"^\s*([A-Za-z]+)\s+(\d{1,2})[,\s]+(\d{4})\s*$")
def _month_day_year(m):
    month = _month_from_name(m.group(1))
    return _validate(_fix_year(int(m.group(3))), month, int(m.group(2)))


# --- "DD Month YYYY" ---
@_register(r"^\s*(\d{1,2})\s+([A-Za-z]+)[,\s]+(\d{4})\s*$")
def _day_month_year(m):
    month = _month_from_name(m.group(2))
    return _validate(_fix_year(int(m.group(3))), month, int(m.group(1)))


# --- "Month YYYY" (no day — treat as 1st) ... only if spec permits
#     The spec says parse to (year, month, day) and examples all have days,
#     so we skip this to avoid over-matching.

# --- "YYYY Month DD" ---
@_register(r"^\s*(\d{4})\s+([A-Za-z]+)\s+(\d{1,2})\s*$")
def _year_month_day(m):
    month = _month_from_name(m.group(2))
    return _validate(_fix_year(int(m.group(1))), month, int(m.group(3)))


# --- "DD Month YY" (two-digit year) ---
@_register(r"^\s*(\d{1,2})\s+([A-Za-z]+)[,\s]+(\d{2})\s*$")
def _day_month_short_year(m):
    month = _month_from_name(m.group(2))
    return _validate(_fix_year(int(m.group(3))), month, int(m.group(1)))


# --- "Month DD, YY" (two-digit year) ---
@_register(r"^\s*([A-Za-z]+)\s+(\d{1,2})[,\s]+(\d{2})\s*$")
def _month_day_short_year(m):
    month = _month_from_name(m.group(1))
    return _validate(_fix_year(int(m.group(3))), month, int(m.group(2)))


# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------

def parse_date(s: str) -> tuple[int, int, int]:
    """Parse a date string and return (year, month, day)."""
    if not isinstance(s, str):
        raise ValueError(f"Expected a string, got {type(s).__name__!r}")
    for regex, handler in _PATTERNS:
        match = regex.match(s)
        if match:
            try:
                return handler(match)
            except ValueError:
                # Bad calendar date (e.g. Feb 30) — re-raise
                raise
    raise ValueError(f"Cannot parse date string: {s!r}")

